// rpcSuitable: the names of the methods net/rpc's suitableMethods registers (models/rpcdesc's
// copy of it is what the codec was generated from; this checks the generated table is current).
func rpcSuitable(typ reflect.Type) []string {
	var ms []string
	errT := reflect.TypeFor[error]()
	exported := func(t reflect.Type) bool {
		for t.Kind() == reflect.Pointer {
			t = t.Elem()
		}
		return t.PkgPath() == "" || (t.Name() != "" && t.Name()[0] >= 'A' && t.Name()[0] <= 'Z')
	}
	for i := 0; i < typ.NumMethod(); i++ {
		m := typ.Method(i)
		mt := m.Type
		if !m.IsExported() || mt.NumIn() != 3 || mt.NumOut() != 1 || mt.Out(0) != errT {
			continue
		}
		if !exported(mt.In(1)) || mt.In(2).Kind() != reflect.Pointer || !exported(mt.In(2)) {
			continue
		}
		ms = append(ms, m.Name)
	}
	return ms
}

func TestRPCReceivers(t *testing.T) {
	if got, want := fmt.Sprint(rpcSuitable(reflect.TypeFor[*p_rpctransport.RaftRPC]())), fmt.Sprint([]string{"AppendEntries", "InstallSnapshot", "RequestPreVote", "RequestVote", "TimeoutNow"}); got != want {
		t.Errorf("*p_rpctransport.RaftRPC: generated for %s, net/rpc registers %s (regenerate)", want, got)
	}
	if got, want := fmt.Sprint(rpcSuitable(reflect.TypeFor[*service.API]())), fmt.Sprint([]string{"AddNonvoter", "AddVoter", "Apply", "DemoteVoter", "LeadershipTransfer", "Read", "RemoveServer", "Snapshot", "Status"}); got != want {
		t.Errorf("*service.API: generated for %s, net/rpc registers %s (regenerate)", want, got)
	}
}
